    // In readonly mode, we don't allow any writes through to the pty.
    if (self.readonly) {

const simd = @import("simd/main.zig");
const crash = @import("crash/main.zig");
const unicode = @import("unicode/main.zig");
const rendererpkg = @import("renderer.zig");
